11	// These tests pin the rule that a plan's raw name literals must decode
12	// exactly as written. encoding/json silently rewrites invalid UTF-8 bytes
13	// and unpaired \u surrogate escapes to U+FFFD, so a corrupted name could
14	// collide with a genuinely different dataset ("源" plus a broken byte would
15	// delete the dataset really named "源�"). The reader must refuse the whole
16	// plan instead of guessing which dataset the user meant.
17	
18	// TestUnmarshalPlanRejectsCorruptNameBytes: a raw string literal carrying
19	// bytes that are not valid UTF-8 rejects the whole plan, in every position
20	// that takes part in the adjustment — a change record's name, any upstreams
21	// entry, and any removals entry. The error names the field and the
22	// zero-based record or array position and says the bytes are invalid.
23	func TestUnmarshalPlanRejectsCorruptNameBytes(t *testing.T) {
24		cases := map[string]struct {
25			data     string
26			field    string
27			location string
28		}{
29			"change name": {
30				`{"changes":[{"name":"source` + "\xff" + `","upstreams":[]}]}`,
31				`"name"`, `index 0 of "changes"`,
32			},
33			"change name in second record": {
34				`{"changes":[{"name":"A","upstreams":[]},{"name":"b` + "\xfe" + `","upstreams":[]}]}`,
35				`"name"`, `index 1 of "changes"`,
36			},
37			"upstream entry": {
38				`{"changes":[{"name":"A","upstreams":["ok","g` + "\xfe" + `"]}]}`,
39				`"upstreams"`, `index 1`,
40			},
41			"upstream entry in second record": {
42				`{"changes":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A","x` + "\xff" + `"]}]}`,
43				`"upstreams"`, `index 1`,
44			},
45			"removals entry": {
46				`{"removals":["a","b","c` + "\xc3" + `"]}`,
47				`"removals"`, `index 2`,
48			},
49			"removals entry naming a dataset that does not exist": {
50				// Even a name that would only delete a nonexistent dataset is
51				// refused: the reader must not treat the corruption as a no-op.
52				`{"removals":["ghost` + "\xff" + `"]}`,
53				`"removals"`, `index 0`,
54			},
55			"case-folded known field is still checked": {
56				`{"CHANGES":[{"NAME":"a` + "\xff" + `"}]}`,
57				`"name"`, `index 0 of "changes"`,
58			},
59			"escaped key spelling is still checked": {
60				`{"changes":[{"na\u006de":"a` + "\xff" + `"}]}`,
61				`"name"`, `index 0 of "changes"`,
62			},
63		}
64		for name, tc := range cases {
65			t.Run(name, func(t *testing.T) {
66				_, err := UnmarshalPlan([]byte(tc.data))
67				if !errors.Is(err, ErrInvalidArgument) {
68					t.Fatalf("err = %v, want ErrInvalidArgument", err)
69				}
70				msg := err.Error()
71				if !strings.Contains(msg, "invalid UTF-8 bytes") {
72					t.Errorf("err = %q, want it to say the bytes are invalid UTF-8", msg)
73				}
74				if strings.Contains(msg, "surrogate") {
75					t.Errorf("err = %q, byte corruption must not be reported as a surrogate problem", msg)
76				}
77				if !strings.Contains(msg, tc.field) {
78					t.Errorf("err = %q, want it to name field %s", msg, tc.field)
79				}
80				if !strings.Contains(msg, tc.location) {
81					t.Errorf("err = %q, want it to locate %s", msg, tc.location)
82				}
83				if strings.Contains(msg, "�") {
84					t.Errorf("err = %q, must not contain the replacement character", msg)
85				}
86			})
87		}
88	}
89	
90	// TestUnmarshalPlanRejectsUnpairedSurrogates: a \u escape forming an
91	// unpaired surrogate — a lone high or low surrogate, a low surrogate before
92	// its high surrogate, or a high surrogate not immediately followed by its
93	// low surrogate — rejects the whole plan, in every name position. The error
94	// says the surrogate escape is unpaired and locates the field.
95	func TestUnmarshalPlanRejectsUnpairedSurrogates(t *testing.T) {
96		cases := map[string]struct {
97			data     string
98			field    string
99			location string
100		}{
101			"lone high surrogate in name": {
102				`{"changes":[{"name":"a\ud800x","upstreams":[]}]}`,
103				`"name"`, `index 0 of "changes"`,
104			},
105			"high surrogate at end of name": {
106				`{"changes":[{"name":"a\ud800","upstreams":[]}]}`,
107				`"name"`, `index 0 of "changes"`,
108			},
109			"lone low surrogate in name": {
110				`{"changes":[{"name":"a\udc00","upstreams":[]}]}`,
111				`"name"`, `index 0 of "changes"`,
112			},
113			"low surrogate before high surrogate": {
114				`{"changes":[{"name":"a\udc00\ud800","upstreams":[]}]}`,
115				`"name"`, `index 0 of "changes"`,
116			},
117			"high surrogate then non-surrogate escape": {
118				`{"changes":[{"name":"a\ud800\u0041","upstreams":[]}]}`,
119				`"name"`, `index 0 of "changes"`,
120			},
121			"high surrogate then another high surrogate": {
122				`{"changes":[{"name":"a\ud800\ud801","upstreams":[]}]}`,
123				`"name"`, `index 0 of "changes"`,
124			},
125			"surrogate in second change record": {
126				`{"changes":[{"name":"A","upstreams":[]},{"name":"\ud800","upstreams":[]}]}`,
127				`"name"`, `index 1 of "changes"`,
128			},
129			"surrogate in upstream entry": {
130				`{"changes":[{"name":"A","upstreams":["ok","\udfff"]}]}`,
131				`"upstreams"`, `index 1`,
132			},
133			"surrogate in removals entry": {
134				`{"removals":["ok","\ud800"]}`,
135				`"removals"`, `index 1`,
136			},
137			"surrogate naming a dataset that does not exist": {
138				`{"removals":["ghost\ud800"]}`,
139				`"removals"`, `index 0`,
140			},
141		}
142		for name, tc := range cases {
143			t.Run(name, func(t *testing.T) {
144				// Premise: the decoder really would silently rewrite these to
145				// U+FFFD instead of failing, which is why the raw check exists.
146				var decoded struct {
147					Changes []struct {
148						Name string `json:"name"`
149					} `json:"changes"`
150				}
151				_ = json.Unmarshal([]byte(tc.data), &decoded)
152	
153				_, err := UnmarshalPlan([]byte(tc.data))
154				if !errors.Is(err, ErrInvalidArgument) {
155					t.Fatalf("err = %v, want ErrInvalidArgument", err)
156				}
157				msg := err.Error()
158				if !strings.Contains(msg, "unpaired surrogate") {
159					t.Errorf("err = %q, want it to say the surrogate escape is unpaired", msg)
160				}
161				if strings.Contains(msg, "invalid UTF-8 bytes") {
162					t.Errorf("err = %q, a surrogate problem must not be reported as invalid bytes", msg)
163				}
164				if !strings.Contains(msg, tc.field) {
165					t.Errorf("err = %q, want it to name field %s", msg, tc.field)
166				}
167				if !strings.Contains(msg, tc.location) {
168					t.Errorf("err = %q, want it to locate %s", msg, tc.location)
169				}
170			})
171		}
172	}
173	
174	// TestUnmarshalPlanCorruptNameRejectsWholePlan: one corrupt name refuses
175	// the entire plan — the other, perfectly legal adjustments in the same
176	// batch must not take effect either.
177	func TestUnmarshalPlanCorruptNameRejectsWholePlan(t *testing.T) {
178		data := `{"changes":[{"name":"A","upstreams":[]},{"name":"b` + "\xff" + `","upstreams":[]}],"removals":["C"]}`
179		if _, err := UnmarshalPlan([]byte(data)); err == nil {
180			t.Fatal("a plan mixing legal records with one corrupt name must be rejected as a whole")
181		}
182	}
183	
184	// TestUnmarshalPlanAcceptsGenuineUnicodeNames: names that are legal stay
185	// byte-for-byte intact — a genuine replacement character (written directly
186	// or as its escape), correctly paired surrogate escapes, CJK, combining
187	// marks, casing, surrounding spaces, and names that merely look like
188	// escapes (a backslash before an ordinary letter).
189	func TestUnmarshalPlanAcceptsGenuineUnicodeNames(t *testing.T) {
190		cases := map[string]struct {
191			data string
192			want string
193		}{
194			"genuine replacement character": {
195				`{"changes":[{"name":"源�","upstreams":[]}]}`,
196				"源�",
197			},
198			"replacement character via escape": {
199				`{"changes":[{"name":"源\ufffd","upstreams":[]}]}`,
200				"源�",
201			},
202			"paired surrogate escape": {
203				`{"changes":[{"name":"ledger\ud83d\ude00","upstreams":[]}]}`,
204				"ledger😀",
205			},
206			"paired surrogate at string start and end": {
207				`{"changes":[{"name":"\ud83d\ude00x\ud83c\udf10","upstreams":[]}]}`,
208				"😀x🌐",
209			},
210			"cjk combining marks casing and spaces": {
211				`{"changes":[{"name":" 数据 Éé ","upstreams":[]}]}`,
212				" 数据 Éé ",
213			},
214			"backslash before ordinary letter": {
215				`{"changes":[{"name":"a\\nb","upstreams":[]}]}`,
216				`a\nb`,
217			},
218			"backslash before what looks like a surrogate escape": {
219				// The name really contains backslash, 'u', 'd', '8', '0', '0';
220				// it must not be rejected for looking like an escape.
221				`{"changes":[{"name":"x\\ud800","upstreams":[]}]}`,
222				`x\ud800`,
223			},
224			"escaped backslash then real escape": {
225				`{"changes":[{"name":"x\\\nud800","upstreams":[]}]}`,
226				"x\\\nud800",
227			},
228		}
229		for name, tc := range cases {
230			t.Run(name, func(t *testing.T) {
231				plan, err := UnmarshalPlan([]byte(tc.data))
232				if err != nil {
233					t.Fatalf("UnmarshalPlan rejected a legal name: %v", err)
234				}
235				if len(plan.Changes) != 1 || plan.Changes[0].Name != tc.want {
236					t.Fatalf("name decoded to %q, want %q kept verbatim", plan.Changes, tc.want)
237				}
238			})
239		}
240	}
241	
242	// TestUnmarshalPlanIgnoresCorruptStringsInUnknownFields: unknown fields and
243	// everything nested inside them keep their ignore-everything behavior —
244	// their strings never take part in the adjustment and are not checked, even
245	// when they spell a known field name one level down.
246	func TestUnmarshalPlanIgnoresCorruptStringsInUnknownFields(t *testing.T) {
247		cases := map[string]string{
248			"corrupt string in unknown top-level field": `{"meta":"a\ud800","changes":[{"name":"A","upstreams":[]}]}`,
249			"corrupt bytes in unknown record field":     `{"changes":[{"name":"A","note":"x` + "\xff" + `","upstreams":[]}]}`,
250			"known field names nested inside unknown field": `{"also":{"changes":[{"name":"\ud800"}],"removals":["g` + "\xff" + `"]},` +
251				`"changes":[{"name":"A","upstreams":[]}]}`,
252			"deeply nested corrupt strings in unknown field": `{"changes":[{"name":"A","upstreams":[],"extra":{"deep":["\udc00",{"k":"v` + "\xfe" + `"}]}}]}`,
253			"unknown field that merely prefixes a known one": `{"changesX":[{"name":"\ud800"}],"removals2":["a` + "\xff" + `"],"changes":[]}`,
254		}
255		for name, data := range cases {
256			t.Run(name, func(t *testing.T) {
257				if _, err := UnmarshalPlan([]byte(data)); err != nil {
258					t.Fatalf("unknown-field strings must not be checked, got %v", err)
259				}
260			})
261		}
262	}
263	
264	// TestUnmarshalPlanEquivalentEscapesSameDataset: legal text written
265	// directly and the same text written with equivalent JSON escapes name the
266	// same dataset and produce the same report.
267	func TestUnmarshalPlanEquivalentEscapesSameDataset(t *testing.T) {
268		graphData := `{"datasets":[{"name":"数据集","upstreams":[]},{"name":"源�","upstreams":[]}]}`
269		graph, err := UnmarshalGraphFile([]byte(graphData))
270		if err != nil {
271			t.Fatalf("UnmarshalGraphFile: %v", err)
272		}
273	
274		direct := `{"changes":[{"name":"数据集","upstreams":["源�"]}],"removals":["旧�"]}`
275		escaped := `{"changes":[{"name":"\u6570\u636e\u96c6","upstreams":["\u6e90\ufffd"]}],"removals":["\u65e7\ufffd"]}`
276		if direct == escaped {
277			t.Fatal("test premise broken: the two spellings must differ as text")
278		}
279	
280		planDirect, err := UnmarshalPlan([]byte(direct))
281		if err != nil {
282			t.Fatalf("direct spelling rejected: %v", err)
283		}
284		planEscaped, err := UnmarshalPlan([]byte(escaped))
285		if err != nil {
286			t.Fatalf("escaped spelling rejected: %v", err)
287		}
288		if !reflect.DeepEqual(planDirect, planEscaped) {
289			t.Fatalf("equivalent spellings decoded differently:\n%+v\n%+v", planDirect, planEscaped)
290		}
291	
292		reportDirect, err := PreviewBatch(graph, planDirect)
293		if err != nil {
294			t.Fatalf("PreviewBatch direct: %v", err)
295		}
296		reportEscaped, err := PreviewBatch(graph, planEscaped)
297		if err != nil {
298			t.Fatalf("PreviewBatch escaped: %v", err)
299		}
300		jDirect, _ := json.Marshal(reportDirect)
301		jEscaped, _ := json.Marshal(reportEscaped)
302		if string(jDirect) != string(jEscaped) {
303			t.Fatalf("reports differ between spellings:\n%s\n%s", jDirect, jEscaped)
304		}
305		if len(reportDirect.ChangedDatasets) != 1 || reportDirect.ChangedDatasets[0] != "数据集" {
306			t.Fatalf("expected 数据集 to be the changed dataset, got %v", reportDirect.ChangedDatasets)
307		}
308	}
309	
310	// TestUnmarshalPlanCorruptNameNeverTouchesGraph: a plan rejected for a
311	// corrupt name leaves the graph it would have been applied to completely
312	// unchanged — including when the corrupt name could have deleted a real
313	// dataset after the decoder's silent rewrite.
314	func TestUnmarshalPlanCorruptNameNeverTouchesGraph(t *testing.T) {
315		graphData := `{"datasets":[{"name":"源�","upstreams":[]},{"name":"down","upstreams":["源�"]}]}`
316		graph, err := UnmarshalGraphFile([]byte(graphData))
317		if err != nil {
318			t.Fatalf("UnmarshalGraphFile: %v", err)
319		}
320		before := snapshotGraph(graph)
321	
322		// "源" plus one broken byte decodes to the real dataset "源�": accepting
323		// it would delete a dataset the user never named.
324		if _, err := UnmarshalPlan([]byte(`{"removals":["源` + "\xff" + `"]}`)); err == nil {
325			t.Fatal("corrupt removal name must be rejected")
326		}
327		if after := snapshotGraph(graph); !reflect.DeepEqual(after, before) {
328			t.Fatalf("graph changed while reading a rejected plan:\nbefore %#v\nafter  %#v", before, after)
329		}
330	}
